local Scribe = {}
local DOCS = {
    contract = { name = "Pogodba", time = 2, cost = 50, knowledge = 5, description = "Pravna pogodba." },
    deed = { name = "Listina", time = 3, cost = 100, prestige = 3, description = "Lastninska listina." },
    warrant = { name = "Odredba", time = 1, cost = 30, description = "Sodna odredba." },
    diploma = { name = "Diploma", time = 5, cost = 200, prestige = 10, description = "Plemiška diploma." },
    bull = { name = "Bula", time = 7, cost = 500, prestige = 20, faith = 10, description = "Papeška bula." },
    chronicle = { name = "Zapis", time = 4, cost = 150, knowledge = 15, description = "Uradni zapis dogodka." },
}
local BUILDINGS = {
    scriptorium = { name = "Skriptorij", cost = { gold = 300, wood = 100 }, upkeep = 8, qualityBonus = 5 },
    chancery = { name = "Kancelarija", cost = { gold = 1000, wood = 200, stone = 200 }, upkeep = 25, qualityBonus = 15 },
    notary_office = { name = "Notarska pisarna", cost = { gold = 1500, wood = 200, stone = 300 }, upkeep = 35, qualityBonus = 20, prestigeBonus = 5 },
    royal_chancery = { name = "Kraljevska kancelarija", cost = { gold = 5000, wood = 400, stone = 800 }, upkeep = 100, qualityBonus = 40, prestigeBonus = 20 },
}
Scribe.documents = {}; Scribe.buildings = {}; Scribe.scribe = nil; Scribe.activeWriting = {}; Scribe.totalDocs = 0; Scribe.dayTimer = 0
function Scribe.init() Scribe.documents={}; Scribe.buildings={}; Scribe.scribe=nil; Scribe.activeWriting={}; Scribe.totalDocs=0; Scribe.dayTimer=0; print("[Scribe] Royal Scribe & Notary System initialized (6 docs, 4 buildings)") end
function Scribe.hireScribe(n,s) s=s or math.random(40,85); local c=300+s*6; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Scribe.scribe={name=n or ("Pisar "..math.random(1,99)),skill=s,hiredDay=os.time(),docsWritten=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pisar najet: %s (spretnost: %d)",Scribe.scribe.name,s),"success") end; return true end
function Scribe.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Scribe.build(id) local ok,e=Scribe.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Scribe.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Scribe.getQualityBonus() local b=0; for _,bd in ipairs(Scribe.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Scribe.canWrite(dt) local dD=DOCS[dt]; if not dD then return false,"Neznan dokument" end; if not _G.state or (_G.state.gold or 0)<dD.cost then return false,"Premalo zlata" end; if #Scribe.buildings==0 then return false,"Potrebna pisarna" end; if not Scribe.scribe then return false,"Potreben pisar" end; return true end
function Scribe.write(dt) local ok,e=Scribe.canWrite(dt); if not ok then return false,e end; local dD=DOCS[dt]; _G.state.gold=_G.state.gold-dD.cost; local t=dD.time; if Scribe.scribe then t=math.max(1,t-math.floor(Scribe.scribe.skill/15)) end; table.insert(Scribe.activeWriting,{id="doc_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),docType=dt,docName=dD.name,cost=dD.cost,prestige=dD.prestige or 0,knowledge=dD.knowledge or 0,faith=dD.faith or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pisanje: %s (%d dni)",dD.name,t),"info") end; return true end
function Scribe.completeWriting(w) local q=1.0+(Scribe.getQualityBonus()/100); if Scribe.scribe then q=q+(Scribe.scribe.skill/200) end; q=math.min(2.0,q); table.insert(Scribe.documents,{id=w.id,type=w.docName,quality=q,value=math.floor(w.cost*q),prestige=math.floor(w.prestige*q),knowledge=math.floor(w.knowledge*q),faith=math.floor(w.faith*q),writtenDay=os.time()}); Scribe.totalDocs=Scribe.totalDocs+1; if _G.Culture then pcall(function() _G.Culture.knowledgePoints=(_G.Culture.knowledgePoints or 0)+w.knowledge end) end; if w.faith>0 and _G.Religion then pcall(_G.Religion.addFaith,w.faith) end; if Scribe.scribe then Scribe.scribe.docsWritten=Scribe.scribe.docsWritten+1; if math.random()<0.15 then Scribe.scribe.skill=math.min(100,Scribe.scribe.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dokument napisan: %s (kakovost: %.1f)",w.docName,q),"success") end end
function Scribe.update(dt) if not _G.state then return end; Scribe.dayTimer=Scribe.dayTimer+dt; if Scribe.dayTimer>=30 then Scribe.dayTimer=0; for i=#Scribe.activeWriting,1,-1 do local w=Scribe.activeWriting[i]; w.daysRemaining=w.daysRemaining-1; if w.daysRemaining<=0 then Scribe.completeWriting(w); table.remove(Scribe.activeWriting,i) end end; local tu=0; for _,bd in ipairs(Scribe.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Scribe.scribe then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Scribe.getStats() return {numDocs=#Scribe.documents,numBuildings=#Scribe.buildings,hasScribe=Scribe.scribe~=nil,scribeName=Scribe.scribe and Scribe.scribe.name or "—",scribeSkill=Scribe.scribe and Scribe.scribe.skill or 0,activeWriting=#Scribe.activeWriting,totalDocs=Scribe.totalDocs} end
return Scribe
